/* The GUIX 5.4.0 integer trigonometry, for negative angles and for arguments
   outside the arc sine's domain.

   With GUIX_5_4_0_COMPATIBILITY, gx_utility_math_sin and gx_utility_math_cos
   take an angle in 1/256 degree and return the value scaled by 256;
   gx_utility_math_asin and gx_utility_math_acos take x scaled by 256 and
   return whole degrees.

   The expected values come from the C library, scaled the same way:
   256 * sin(angle / 256 degrees) and 256 * cos(angle / 256 degrees), within
   2, since GUIX reads a table of quarter degrees truncated to whole 1/256
   units; asin(x / 256) and acos(x / 256) in degrees, within 1, at points away
   from the three largest table entries, x = 252, 254 and 255, which are 1 to
   5 degrees above the C library's value. An x outside [-256, 256] has no arc
   sine: the functions return their initial value, 0 for asin, and acos
   returns 90 - asin. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_utility_math_5_4_0_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

#define TEST_PI 3.14159265358979323846

static UINT      failed_tests = 0;

static TX_THREAD test_thread;
static ULONG     test_thread_stack[8192 / sizeof(ULONG)];

/* Negative angles, one in each quadrant after the turn is added, and more than a turn below zero.  */
static const INT test_angles[] = {-1, -256, -5000, -30000, -50000, -80000, -92160, -100000, -200000};

/* Arc sine arguments, in and outside the domain.  */
static const INT test_x[] = {-256, -200, -128, 0, 128, 200, 256};
static const INT test_outside_x[] = {257, 300, 1000, -257, -300, -1000};

static VOID test_thread_entry(ULONG id)
{
UINT   index;
INT    angle;
INT    x;
double radians;
double expected;
INT    value;

    setvbuf(stdout, NULL, _IONBF, 0);

    for (index = 0; index < sizeof(test_angles) / sizeof(test_angles[0]); index++)
    {
        angle = test_angles[index];
        radians = (double)angle / 256.0 * TEST_PI / 180.0;

        value = gx_utility_math_sin(angle);
        expected = 256.0 * sin(radians);
        if (fabs(value - expected) >= 2.0)
        {
            printf("sin(%d) = %d, expected %.2f\n", angle, value, expected);
            failed_tests++;
        }

        value = gx_utility_math_cos(angle);
        expected = 256.0 * cos(radians);
        if (fabs(value - expected) >= 2.0)
        {
            printf("cos(%d) = %d, expected %.2f\n", angle, value, expected);
            failed_tests++;
        }
    }

    for (index = 0; index < sizeof(test_x) / sizeof(test_x[0]); index++)
    {
        x = test_x[index];

        value = gx_utility_math_asin(x);
        expected = asin((double)x / 256.0) * 180.0 / TEST_PI;
        if (fabs(value - expected) >= 1.0)
        {
            printf("asin(%d) = %d, expected %.2f\n", x, value, expected);
            failed_tests++;
        }

        value = gx_utility_math_acos(x);
        expected = acos((double)x / 256.0) * 180.0 / TEST_PI;
        if (fabs(value - expected) >= 1.0)
        {
            printf("acos(%d) = %d, expected %.2f\n", x, value, expected);
            failed_tests++;
        }
    }

    for (index = 0; index < sizeof(test_outside_x) / sizeof(test_outside_x[0]); index++)
    {
        x = test_outside_x[index];
        EXPECT_EQ(0, gx_utility_math_asin(x));
        EXPECT_EQ(90, gx_utility_math_acos(x));
    }

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

